package android.database.sqlite;
import android.content.Context; import java.io.*; import java.sql.*;
public abstract class SQLiteOpenHelper { final Context ctx; final String name; final int version; SQLiteDatabase db; public SQLiteOpenHelper(Context c,String n,Object f,int v){ctx=c;name=n;version=v;} public abstract void onCreate(SQLiteDatabase d); public abstract void onUpgrade(SQLiteDatabase d,int a,int b); public synchronized SQLiteDatabase getWritableDatabase(){try{if(db==null){File f=ctx.getDatabasePath(name);f.getParentFile().mkdirs();Connection c=DriverManager.getConnection("jdbc:sqlite:"+f);db=new SQLiteDatabase(c);int old;try(Statement s=c.createStatement();ResultSet r=s.executeQuery("PRAGMA user_version")){old=r.next()?r.getInt(1):0;}if(old==0)onCreate(db);else if(old<version)onUpgrade(db,old,version);if(old!=version)try(Statement s=c.createStatement()){s.execute("PRAGMA user_version="+version);}}return db;}catch(Exception e){throw new RuntimeException(e);}} public SQLiteDatabase getReadableDatabase(){return getWritableDatabase();} }
